// Blossoms - pink and white
const blossoms = [
    {x: 170, y: 280, size: 8, petals: 8},
    {x: 190, y: 270, size: 6, petals: 6},
    {x: 160, y: 290, size: 7, petals: 7},
    {x: 185, y: 285, size: 5, petals: 5}
];

// Draw petals
ctx.fillStyle = '#ffd1dc';
for(const blossom of blossoms) {
    ctx.beginPath();
    ctx.arc(blossom.x, blossom.y, blossom.size, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    for(let i = 0; i < blossom.petals; i++) {
        const angle = (i / blossom.petals) * Math.PI * 2;
        const px = blossom.x + Math.cos(angle) * blossom.size;
        const py = blossom.y + Math.sin(angle) * blossom.size;
        ctx.beginPath();
        ctx.moveTo(blossom.x, blossom.y);
        ctx.lineTo(px, py);
        ctx.stroke();
    }
}

