// Watch hands
const now = new Date();
const hours = now.getHours() % 12;
const minutes = now.getMinutes();
const seconds = now.getSeconds();

// Hour hand
const hourAngle = ((hours + minutes / 60) / 12) * Math.PI * 2;
const hourX = 200 + Math.cos(hourAngle) * 70;
const hourY = 200 - Math.sin(hourAngle) * 70;
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(200, 200);
ctx.lineTo(hourX, hourY);
ctx.stroke();

// Minute hand
const minuteAngle = (minutes / 60) * Math.PI * 2;
const minuteX = 200 + Math.cos(minuteAngle) * 85;
const minuteY = 200 - Math.sin(minuteAngle) * 85;
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(200, 200);
ctx.lineTo(minuteX, minuteY);
ctx.stroke();

// Second hand
const secondAngle = (seconds / 60) * Math.PI * 2;
const secondX = 200 + Math.cos(secondAngle) * 90;
const secondY = 200 - Math.sin(secondAngle) * 90;
ctx.strokeStyle = '#ff0000';
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(200, 200);
ctx.lineTo(secondX, secondY);
ctx.stroke();

// Center circle
