ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(hourX, hourY);
ctx.lineTo(hourX + 3, hourY + 3);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(minuteX, minuteY);
ctx.lineTo(minuteX + 2, minuteY + 2);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(secondX, secondY);
ctx.lineTo(secondX + 1, secondY + 1);
ctx.stroke();

