  {x: 100, y: 250, size: 15, value: 1},
  {x: 200, y: 270, size: 18, value: 2},
  {x: 300, y: 240, size: 12, value: 1},
  {x: 150, y: 280, size: 16, value: 3},
  {x: 350, y: 260, size: 14, value: 2},
  {x: 120, y: 290, size: 13, value: 1},
  {x: 320, y: 270, size: 17, value: 4}
];

// Draw coins
coins.forEach(coin => {
  const cx = coin.x - coin.size/2;
  const cy = coin.y - coin.size/2;

  // Main body of coin
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(cx, cy, coin.size, coin.size);

  // Highlight
  ctx.fillStyle = '#FFA500';
  ctx.fillRect(cx + 2, cy + 2, coin.size - 4, coin.size - 4);

  // Shadow
  ctx.fillStyle = '#C0C0C0';
  ctx.fillRect(cx + 3, cy + 3, coin.size - 6, coin.size - 6);

  // Value number
  ctx.fillStyle = '#000000';
  ctx.font = '12px Arial';
  ctx.fillText(coin.value.toString(), cx + coin.size/2 - 2, cy + coin.size/2 + 2);
});

